/**
 * Button — generated by the React Native Reusables CLI (`button`), re-skinned.
 *
 * Deviations from upstream:
 * - `default` is the one accent-filled control a screen may draw
 *   (docs/design-guidelines.md, the accent budget). It presses to `accent-hover`
 *   rather than `primary/90`: the palette is hex variables, so an opacity modifier
 *   has nothing to apply to.
 * - `outline` is the quiet button: a `card` object with a hairline edge, lifted at
 *   `sm` through `useElevation` (React Native `boxShadow`; NativeWind's `shadow-*`
 *   cannot carry the per-theme layers). Upstream's `bg-accent` press is shadcn's
 *   hover token, which this palette does not have — presses go to `muted`.
 * - `destructive` fills `live-fill` with `on-live-fill` text, the pair measured
 *   for it, instead of `text-white` on `destructive/60`.
 * - Every `dark:` variant is gone; the variables change with the theme instead.
 * - Sizes are touch sizes: 48 is the default and the minimum target, the `sm:`
 *   desktop steps are removed, and the label is `text-base font-semibold`.
 * - React 19 idioms: `use` and `<Context value>`, and no extra `RefAttributes` —
 *   `ComponentProps` already carries `ref`, and upstream's second ref type made
 *   every `useRef` passed as `ref` a type error.
 */
import { TextClassContext } from '@/components/ui/text';
import { cn } from '@/lib/utils';
import { useElevation } from '@/ui/elevation';
import { cva, type VariantProps } from 'class-variance-authority';
import { Platform, Pressable } from 'react-native';

const buttonVariants = cva(
  cn(
    'group shrink-0 flex-row items-center justify-center gap-2 rounded-md',
    Platform.select({
      web: 'focus-visible:ring-ring whitespace-nowrap outline-none focus-visible:ring-2 disabled:pointer-events-none [&_svg]:pointer-events-none [&_svg]:shrink-0',
    }),
  ),
  {
    variants: {
      variant: {
        default: 'bg-primary active:bg-accent-hover',
        destructive: 'bg-live-fill active:opacity-90',
        outline: 'border border-border bg-card active:bg-muted',
        secondary: 'bg-secondary active:bg-accent-subtle',
        ghost: 'active:bg-muted',
        link: '',
      },
      size: {
        default: 'h-12 px-4',
        sm: 'h-10 gap-1 px-4',
        lg: 'h-14 px-6',
        icon: 'h-12 w-12',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
);

const buttonTextVariants = cva(
  cn(
    'font-sans text-base font-semibold text-foreground',
    Platform.select({ web: 'pointer-events-none' }),
  ),
  {
    variants: {
      variant: {
        default: 'text-primary-foreground',
        destructive: 'text-on-live-fill',
        outline: 'text-foreground',
        secondary: 'text-secondary-foreground',
        ghost: 'text-foreground',
        // A link is ink like the text around it, so it carries an underline at
        // rest (WCAG 1.4.1) — colour alone marks nothing in this palette.
        link: 'text-accent-text underline',
      },
      size: {
        default: '',
        sm: 'text-sm',
        lg: '',
        icon: '',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
);

type ButtonProps = React.ComponentProps<typeof Pressable> & VariantProps<typeof buttonVariants>;

function Button({ className, variant, size, style, ...props }: ButtonProps) {
  const lift = useElevation('sm');
  const lifted = variant === 'outline' && !props.disabled;
  return (
    <TextClassContext value={buttonTextVariants({ variant, size })}>
      <Pressable
        className={cn(props.disabled && 'opacity-50', buttonVariants({ variant, size }), className)}
        role="button"
        style={
          lifted
            ? typeof style === 'function'
              ? (state) => [lift, style(state)]
              : [lift, style]
            : style
        }
        {...props}
      />
    </TextClassContext>
  );
}

export { Button, buttonTextVariants, buttonVariants };
export type { ButtonProps };
